import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import EventCard from "./events/EventCard";
import Chatbot from "./Chatbot";

export default function Home() {
  const [events, setEvents] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/dashboard/events")
      .then((r) => r.json())
      .then(setEvents)
      .catch(console.error);
  }, []);

  return (
    <div id="home-section" className="home-page">

      {/* 🔵 HERO BANNER */}
      <section
        className="hero"
        style={{
          backgroundImage:
            "url('https://images.unsplash.com/photo-1509099836639-18ba1795216d?auto=format&fit=crop&w=1350&q=80')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          height: "80vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "white",
          textShadow: "0 0 8px black",
          fontSize: "48px",
          fontWeight: "bold",
        }}
      >
        Making Communities Stronger Together.
      </section>

      {/* 🔵 ABOUT US */}
      <section id="about-section" className="section">
        <h2>About Us</h2>
        <p>
          HelpingHands works in education, healthcare, women empowerment, and community support
          programs with volunteers across India.
        </p>

        <img
          src="https://images.unsplash.com/photo-1497493292307-31c376b6e479?auto=format&fit=crop&w=1350&q=80"
          alt="NGO Work"
          style={{
            width: "100%",
            borderRadius: 10,
            marginTop: 16,
            maxHeight: "350px",
            objectFit: "cover",
          }}
        />
      </section>

      {/* 🔵 EVENTS SECTION */}
      <section id="events-section" className="section">
        <h2>Upcoming Events</h2>

        <div className="cards">
          {events.slice(0, 3).map((ev) => (
            <EventCard
              key={ev.id}
              event={ev}
              onClick={() => navigate(`/events/${ev.id}`)}
            />
          ))}
        </div>

        <button
          onClick={() => navigate("/events")}
          style={{
            marginTop: 20,
            padding: "10px 20px",
            background: "#0077cc",
            color: "white",
            border: "none",
            borderRadius: 6,
            cursor: "pointer",
          }}
        >
          View More Events →
        </button>
      </section>

      {/* 🔵 CONTACT US */}
      <section id="contact-section" className="section">
        <h2>Contact Us</h2>

        <p><strong>Phone:</strong> +91 98765 43210</p>
        <p><strong>Email:</strong> support@ngoportal.org</p>

        <img
          src="https://images.unsplash.com/photo-1521790361543-f645cf042ec4?auto=format&fit=crop&w=1350&q=80"
          alt="Contact"
          style={{
            width: "100%",
            borderRadius: 10,
            marginTop: 16,
            maxHeight: 350,
            objectFit: "cover",
          }}
        />
      </section>

      <Chatbot />
    </div>
  );
}
